// Chantier secrets (2026-10-13) — DEUX CONTRATS :
//  - lot commité (dépôt public) : SANS code_suppression ni prof_email ; s'ils sont
//    présents dans le JSON collé, ils sont IGNORÉS ;
//  - fichier Drive (privé) : complété ICI avec le code généré par n8n (noeud
//    Crypto/Generate ; le module crypto est interdit en noeud Code sur l'instance) et l'adresse
//    routée par matière — lus ensuite par /box-delete (code), box-selection-prof et
//    box-question-eleve (prof_email).
// Plomberie uniquement : AUCUNE régénération de contenu, AUCUN appel réseau ici.

const raw = $json.lot_json;
const data = typeof raw === 'string' ? JSON.parse(raw) : raw;

if (!data || typeof data !== 'object' || data._INSTRUCTION) {
  throw new Error('Colle le JSON complet d\'un lot FONDA dans le noeud "Coller lot FONDA" avant d\'executer ce workflow.');
}
if (!data.id) throw new Error('Champ "id" manquant dans le JSON colle.');
if (!Array.isArray(data.cartes) || data.cartes.length === 0) throw new Error('Champ "cartes" manquant ou vide dans le JSON colle.');

// Aléa du noeud "Generer code suppression" (Crypto/Generate, hex, 16 caractères).
const alea = $json.code_aleatoire;
if (typeof alea !== 'string' || !/^[0-9a-f]{16}$/i.test(alea)) {
  throw new Error('Code aleatoire absent ou invalide : verifier le noeud "Generer code suppression" (Crypto / Generate, hex, longueur 16).');
}
const codeSuppression = 'SUP-' + alea.toUpperCase();

// Routage par matière (AGENTS.md : français -> relectrice de français, maths -> Éric).
// Adresses = PLACEHOLDERS dans le dépôt, remplacées dans n8n après import (jamais
// d'adresse réelle commitée). Garde-fou : refus d'envoyer tant qu'un placeholder reste.
const EMAIL_FRANCAIS = '__EMAIL_TEST__';
const EMAIL_MATHS = '__EMAIL_TEST__';
function routerEmail(matiereLabel) {
  const m = String(matiereLabel || '').toLowerCase();
  const email = m.startsWith('fran') ? EMAIL_FRANCAIS : m.startsWith('math') ? EMAIL_MATHS : null;
  if (!email) throw new Error('Matiere non reconnue pour le routage de relecture : "' + matiereLabel + '"');
  if (email.startsWith('__') || !email.includes('@')) {
    throw new Error('Adresse de relecture non configuree (' + email + ') : remplacer le placeholder dans ce noeud apres import.');
  }
  return email;
}
const profEmail = routerEmail(data.matiere);

// Fichier Drive : on écrase TOUJOURS code et adresse par les valeurs n8n.
const fichier = { ...data, code_suppression: codeSuppression, prof_email: profEmail };
const buffer = Buffer.from(JSON.stringify(fichier, null, 2), 'utf-8');

return [{
  json: {
    id: data.id,
    matiere: data.matiere,
    niveau: data.niveau,
    notion: data.notion,
    code_suppression: codeSuppression,
    cartes: data.cartes,
    nb_cartes: data.cartes.length,
    prof_email_route: profEmail
  },
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, data.id + '.json', 'application/json')
  }
}];

// Repris tel quel de BOX - Generation Flashcards / "Preparer Email Validation"
// (version post-T-SEC, escapeHtml sur tous les champs inseres -- injection HTML
// particulierement sensible ici car les cartes viennent d'un modele).
// Seules 2 adaptations : (1) cartes lues directement sur prevData.cartes (pas
// de flashcard_file, ce workflow ne fait pas d'appel Claude) ; (2) prof_email
// = prevData.prof_email_route (derive de la matiere), jamais un champ prof_email
// qui viendrait du JSON colle.

const prevData = $('Preparer fichier et destinataire').first().json;
const uploadResult = $('Upload Flashcards').first().json;
const driveFileId = uploadResult.id || uploadResult.fileId || '';
const code = prevData.code_suppression;

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const cartes = prevData.cartes || [];
const maxPreview = Math.min(cartes.length, 5);
let cartesHtml = '';
for (let i = 0; i < maxPreview; i++) {
  const c = cartes[i];
  const diff = c.difficulte === 'facile' ? '#16a34a' : c.difficulte === 'moyen' ? '#d97706' : '#dc2626';
  cartesHtml += `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px;margin:8px 0">
    <div style="color:${diff};font-size:12px;font-weight:bold;margin-bottom:4px">${escapeHtml((c.difficulte || '').toUpperCase())}</div>
    <div style="font-weight:bold;margin-bottom:6px">Q${escapeHtml(c.numero)}: ${escapeHtml(c.question)}</div>
    <div style="color:#475569">${escapeHtml(c.reponse)}</div>
  </div>`;
}
if (cartes.length > maxPreview) {
  cartesHtml += `<p style="color:#64748b;text-align:center">... et ${cartes.length - maxPreview} autres cartes</p>`;
}

const baseUrl = 'https://n8n.srv868991.hstgr.cloud/webhook';
const selectUrl = escapeHtml(`${baseUrl}/box-select-test?file_id=${driveFileId}&code=${encodeURIComponent(code)}`);

const emailHtml = `<h2>BOX-FONDA - Fiches a valider</h2>
<p><strong>Matiere :</strong> ${escapeHtml(prevData.matiere)}<br>
<strong>Niveau :</strong> ${escapeHtml(prevData.niveau)}<br>
<strong>Notion :</strong> ${escapeHtml(prevData.notion)}<br>
<strong>Nombre de cartes :</strong> ${cartes.length}</p>
<hr>
<h3>Apercu des cartes generees :</h3>
${cartesHtml}
<hr>
<p style="text-align:center;margin:24px 0">
  <a href="${selectUrl}" style="background:#2563eb;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-size:16px;font-weight:bold">&#128203; Relire et choisir les cartes</a>
</p>
<p style="color:#64748b;font-size:12px;text-align:center">Vous pourrez decocher les cartes a exclure avant publication.<br>
Les fiches selectionnees seront accessibles aux eleves sur <a href="https://ericduchateau.github.io/box/">la page BOX</a>.<br>
Code de suppression (a conserver) : <code>${escapeHtml(prevData.id)}</code> / <code>${escapeHtml(code)}</code></p>`;

return [{ json: {
  prof_email: prevData.prof_email_route,
  notion: prevData.notion,
  email_html: emailHtml
} }];
